using System;
using UnityEngine;
namespace AthenHill
{
    /// The bench's sound events and Brann's lines as an asset (Data/Assembly/AssemblyAudioTable.asset), generated by the
    /// installer from art/steady_hands_bench_20261120/audio/manifest.json and lines.json (CONTRACT.md section C).
    /// An event or line without a clip is silent, not an error: the audio arrives after the system.
    public class AssemblyAudioTable : ScriptableObject
    {
        [Serializable] public class Event
        {
            public string id = "";
            public AudioClip[] clips = new AudioClip[0];
            public bool loop;
            [Range(0, 1.5f)] public float volume = 1;
            public Vector2 pitchRange = new Vector2(.97f, 1.03f);
        }
        [Serializable] public class Line
        {
            public string id = "", speaker = "npc_brann", trigger = "";
            [TextArea] public string text = "";
            public AudioClip clip;
        }
        /// One cell of the contact matrix: the part's material on the surface's material ("*" = any surface).
        [Serializable] public class Contact { public string part = "", surface = "", eventId = ""; }
        public Event[] events = new Event[0];
        public Line[] lines = new Line[0];
        public Contact[] contacts = new Contact[0];
        [Tooltip("SHA-1 of the manifest and lines files this was generated from.")] public string sourceHash = "";

        /// The seat event for two materials: a on b, then b on a, then a on anything. Null when the matrix has none.
        public string ContactEvent(string a, string b)
        {
            foreach (var c in contacts) if (c.part == a && c.surface == b) return c.eventId;
            foreach (var c in contacts) if (c.part == b && c.surface == a) return c.eventId;
            foreach (var c in contacts) if (c.part == a && c.surface == "*") return c.eventId;
            return null;
        }

        public Event Find(string id) { foreach (var e in events) if (e.id == id) return e; return null; }
        public Line FindLine(string trigger) { foreach (var l in lines) if (l.trigger == trigger) return l; return null; }
    }
}
